(() => {
  const path = window.location.pathname.replace(/\/+$/, '/');
  const isEs = path.endsWith('/es/carta-abierta-trabajadores-acosta-matos/');
  const isEn = path.endsWith('/en/open-letter-workers-acosta-matos/');
  if (!isEs && !isEn) return;
  if (document.getElementById('rosa-dorta-direct-call-20260816')) return;

  const headings = [...document.querySelectorAll('h2')];
  const anchor = headings.find((h) => isEs
    ? h.textContent.includes('A quien pueda explicar esa ruta de recuperación')
    : h.textContent.includes('To anyone who can explain that recovery route'));
  if (!anchor) return;

  const existingCall = anchor.nextElementSibling;
  const mountAfter = existingCall && existingCall.classList.contains('call') ? existingCall : anchor;

  const capture = 'data:image/jpeg;base64,';

  const block = document.createElement('div');
  block.id = 'rosa-dorta-direct-call-20260816';
  block.style.margin = '1.6rem 0';

  if (isEs) {
    block.innerHTML = `
      <h2>Rosa María Dorta Perdomo: invitación directa, con el límite probatorio a la vista</h2>
      <div class="call">
        <p><strong>El nombre Rosa María Dorta Perdomo figura en el título descriptivo asignado posteriormente a una de las capturas preservadas del 8 de junio de 2019.</strong> Ese nombre no fue revelado por Google y el título del archivo no prueba por sí solo que ella fuera titular de la dirección de recuperación, administradora de <span class="mono">sunpark264@gmail.com</span> ni autora del correo al cliente.</p>
        <p>Gil Marer decide hacer pública esa <strong>identificación histórica como pista de investigación y como invitación directa, no como conclusión de responsabilidad</strong>.</p>
        <p><strong>Rosa María Dorta Perdomo:</strong> si usted es la persona a la que se refería esa identificación histórica, si trabajó en ese perímetro o si conoce por qué su nombre quedó asociado a este material, le invito expresamente a acudir a Policía Nacional, Guardia Civil, Ministerio Fiscal, juzgado competente, AIPI o, cuando sea seguro y eficaz, al sistema interno de información de su empresa y explicar lo que sabe.</p>
        <p>No afirmo que usted enviara el correo, creara la cuenta, controlara sus credenciales o fuera titular de la dirección de recuperación. Si existe una explicación inocente, una asignación técnica distinta, un error de identificación o cualquier dato que corrija esta pista, <strong>también debe quedar documentado</strong>.</p>
      </div>
      <div class="note">
        <strong>Captura contemporánea adicional — 8 de junio de 2019.</strong>
        <p>Durante la comprobación de dominio quedó preservada esta captura de Hunter.io. Muestra una dirección corporativa parcialmente enmascarada bajo <span class="mono">@acostamatos.com</span> y referencias a fuentes públicas que el servicio decía haber localizado. Es una fuente secundaria de enriquecimiento/búsqueda: <strong>no es Google, no es LinkedIn y no demuestra quién era titular de esa dirección ni que fuese la recuperación configurada en Google.</strong></p>
        <img src="${capture}" alt="Captura histórica de Hunter.io sobre el dominio acostamatos.com preservada el 8 de junio de 2019" style="display:block;width:100%;max-width:760px;height:auto;margin:1rem auto;border:1px solid #ccc;border-radius:10px" loading="lazy">
        <p class="small">La captura se publica para conservar el contexto de la investigación contemporánea. No se reconstruye desde ella una dirección completa.</p>
      </div>
      <div class="note"><strong>Control LinkedIn.</strong><p>Las búsquedas actuales realizadas por nombre completo y por Acosta Matos no han permitido verificar un perfil de LinkedIn que pueda atribuirse inequívocamente a Rosa María Dorta Perdomo. Por ese motivo <strong>no publicamos como suyo el perfil de otra persona llamada Rosa Dorta</strong>. Si se obtiene el URL o una captura inequívoca y verificable, se incorporará con fecha y procedencia.</p></div>`;
  } else {
    block.innerHTML = `
      <h2>Rosa María Dorta Perdomo: a direct invitation, with the evidential limit in plain view</h2>
      <div class="call">
        <p><strong>The name Rosa María Dorta Perdomo appears in the later descriptive filename given to one of the preserved 8 June 2019 captures.</strong> Google did not reveal that name, and the filename does not by itself prove that she owned the recovery address, administered <span class="mono">sunpark264@gmail.com</span>, or authored the customer email.</p>
        <p>Gil Marer has chosen to make that <strong>historical identification public as an investigative lead and a direct invitation, not as a finding of responsibility</strong>.</p>
        <p><strong>Rosa María Dorta Perdomo:</strong> if you are the person referred to by that historical identification, if you worked within that perimeter, or if you know why your name became associated with this material, I expressly invite you to go to the National Police, Guardia Civil, Public Prosecutor, competent court, AIPI or, where safe and effective, your employer's internal information system and explain what you know.</p>
        <p>I am not saying that you sent the email, created the account, controlled its credentials or owned the recovery address. If there is an innocent explanation, a different technical assignment, an identification error or evidence correcting this lead, <strong>that should be documented too</strong>.</p>
      </div>
      <div class="note">
        <strong>Additional contemporaneous capture — 8 June 2019.</strong>
        <p>A Hunter.io domain-search capture was preserved during the contemporaneous check. It displays a partially masked corporate address under <span class="mono">@acostamatos.com</span> and public-source references that the service said it had located. This is a secondary enrichment/search source: <strong>it is not Google, it is not LinkedIn, and it does not establish who owned the address or that it was the Google recovery address.</strong></p>
        <img src="${capture}" alt="Historical Hunter.io capture for the acostamatos.com domain preserved on 8 June 2019" style="display:block;width:100%;max-width:760px;height:auto;margin:1rem auto;border:1px solid #ccc;border-radius:10px" loading="lazy">
        <p class="small">The capture is published to preserve the contemporaneous investigative context. No complete email address is reconstructed from it.</p>
      </div>
      <div class="note"><strong>LinkedIn control.</strong><p>Current searches using the full name and Acosta Matos have not produced a LinkedIn profile that can be attributed unequivocally to Rosa María Dorta Perdomo. We therefore <strong>do not publish another Rosa Dorta's profile as hers</strong>. If an unequivocal, source-verifiable URL or capture is obtained, it can be added with its date and provenance.</p></div>`;
  }

  mountAfter.insertAdjacentElement('afterend', block);
})();
